import{_ as a,H as r,f as t,i}from"./chunks/framework.CxRpNt2Z.js";const d=JSON.parse('{"title":"VO 和 VIO","description":"","frontmatter":{},"headers":[],"relativePath":"notes/大创-无人机与自主导航/02-VO和VIO.md","filePath":"notes/大创-无人机与自主导航/02-VO和VIO.md"}'),l={name:"notes/大创-无人机与自主导航/02-VO和VIO.md"};function o(h,e,n,s,p,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="vo-和-vio" tabindex="-1">VO 和 VIO <a class="header-anchor" href="#vo-和-vio" aria-label="Permalink to &quot;VO 和 VIO&quot;">​</a></h1><h2 id="vo" tabindex="-1">VO <a class="header-anchor" href="#vo" aria-label="Permalink to &quot;VO&quot;">​</a></h2><p>视觉里程计（Visual Odometry，简称VO）是利用<strong>连续图像序列</strong> 估计 相机自身运动（位姿变化）的一种技术。</p><p>它的作用是拿到相机的相对位姿变化(平移和旋转)</p><p>与IMU和激光雷达相比，成本更低，但受限于光照和场景特征等因素。</p><h3 id="基本原理" tabindex="-1">基本原理 <a class="header-anchor" href="#基本原理" aria-label="Permalink to &quot;基本原理&quot;">​</a></h3><ol><li><p>**特征匹配：**就是找出图片中的同一个物体。从连续帧中提取图像特征点，并在相邻帧之间进行匹配。然后跟踪这个特征点。</p></li><li><p>**几何约束与位姿解算：**利用特征点在不同时间(帧)下在画面里的位置，通过几何约束（如本质矩阵、基础矩阵或相机模型）解算摄像头的相对位姿变化。</p></li></ol><p>举个例子：如果你的相机搭载在一台无人机上，而无人机在只有雪白的墙壁的室内飞，那么摄像机拍到的画面都是白花花一片，或者墙壁的纹理是整齐的，重复的，相机拍到的不同画面长得几乎一模一样——这个时候根本没有特征点，无法解算，我们称之为<strong>低纹理环境</strong>。但如果墙上有标记，比如一颗钉子，那么就能以钉子为特征点，用数学解算相机的位姿变化。</p><h3 id="模块和步骤" tabindex="-1">模块和步骤 <a class="header-anchor" href="#模块和步骤" aria-label="Permalink to &quot;模块和步骤&quot;">​</a></h3><ul><li>图像采集和预处理模块</li><li>特征提取描述模块</li><li>特征匹配跟踪模块</li><li>运动解算模块</li><li>优化与滤波</li></ul><ol><li>使用相机获得连续的图像序列</li><li>预处理，滤波去噪，转为灰度图等操作</li><li>特征点检测如Harris角点、FAST、SIFT、SURF等方法，在图像中检测高辨识度的特征点，当然也有论文研究特征线——PL VIO</li><li>为每个特征点生成描述子(SIFT、SURF、ORB等)</li><li>特征匹配，跟踪(Brute-Force,FLANN，Lucas-Kanade等)</li><li>运动解算</li><li>优化(最小二乘，Bundle Adjustment)和滤波(卡尔曼滤波EKF等)</li></ol><h3 id="限制和不足" tabindex="-1">限制和不足 <a class="header-anchor" href="#限制和不足" aria-label="Permalink to &quot;限制和不足&quot;">​</a></h3><ul><li><p>相机的输出频率有限，一般不超过100Hz；</p></li><li><p>在基于单目的VO系统中，不能精准估计尺度信息</p></li><li><p>不适合低纹理（如白墙）</p></li><li><p>不适合高速运动或者高动态的场景（出现曝光过度或者不足）</p></li></ul><h2 id="vio" tabindex="-1">VIO <a class="header-anchor" href="#vio" aria-label="Permalink to &quot;VIO&quot;">​</a></h2><p>视觉惯性里程计(Visual-Inertial Odometry，VIO)，是一个使用一个或者多个相机、一个或者多个IMU进行传感器状态测量的技术(也就是解算位姿)</p><p>相机和IMU相比于其他传感器比较廉价，也比较轻便，因此在现代无人机上普遍配备了VIO</p><p>前面已经讲解了VO和IMU，而VIO设计理念就在于，将相机和IMU两种的传感器进行数据融合，达到“优势互补”。</p><ul><li>IMU弥补输VO出频率不高和过渡依赖光照和速度限制的不足</li><li>VO弥补IMU存在漂移误差的不足</li></ul><p>具体的原理涉及李代数和滤波的数学知识，这个我看以后有没有时间更吧...</p><h3 id="数据融合的方式" tabindex="-1">数据融合的方式 <a class="header-anchor" href="#数据融合的方式" aria-label="Permalink to &quot;数据融合的方式&quot;">​</a></h3><h4 id="松耦合" tabindex="-1">松耦合 <a class="header-anchor" href="#松耦合" aria-label="Permalink to &quot;松耦合&quot;">​</a></h4><p>IMU和相机分别解算完自身的运动估计，然后对结果进行数据融合，鲁棒性不如紧耦合</p><h4 id="紧耦合" tabindex="-1">紧耦合 <a class="header-anchor" href="#紧耦合" aria-label="Permalink to &quot;紧耦合&quot;">​</a></h4><p>先把IMU的状态和相机的状态合并在一起，共同构建运动方程和观测方程，然后进行位姿状态的解算。分为基于滤波(Filter)和基于优化(optimization)两个研究方向</p><h3 id="常见算法" tabindex="-1">常见算法 <a class="header-anchor" href="#常见算法" aria-label="Permalink to &quot;常见算法&quot;">​</a></h3><h4 id="基于滤波器" tabindex="-1">基于滤波器 <a class="header-anchor" href="#基于滤波器" aria-label="Permalink to &quot;基于滤波器&quot;">​</a></h4><ul><li>MSCKF：为了解决EKF-SLAM需要一个初始深度和协方差，选择不正确后面就不会收敛的问题。原始的MSCKF算法提出了一个度量模型，该模型表达了观察特定图像特征的所有相机姿态之间的几何约束，而不需要在状态向量中维护3D路标点位置的估计。Alex Zihao Zhu等人实现了一个基于事件相机（Event-based Camera）输入的使用MSCKF后端的里程计，后面该实现被改造成可接收普通相机特征跟踪信息的版本 仓库： <a href="https://github.com/daniilidis-group/msckf_mono" target="_blank" rel="noreferrer">https://github.com/daniilidis-group/msckf_mono</a> 论文：<a href="https://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&amp;arnumber=8100099" target="_blank" rel="noreferrer">https://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&amp;arnumber=8100099</a></li><li>ROVIO：计算量小，但是没有闭环会残留误差。 仓库：<a href="https://github.com/ethz-asl/rovio" target="_blank" rel="noreferrer">https://github.com/ethz-asl/rovio</a> 论文：<a href="https://www.doc.ic.ac.uk/~sleutene/publications/ijrr2014_revision_1.pdf" target="_blank" rel="noreferrer">https://www.doc.ic.ac.uk/~sleutene/publications/ijrr2014_revision_1.pdf</a></li></ul><h4 id="基于优化" tabindex="-1">基于优化 <a class="header-anchor" href="#基于优化" aria-label="Permalink to &quot;基于优化&quot;">​</a></h4><ul><li><p>OKVIS：前端：多目+IMU 后端：ceres solver优化库，基于关键帧的滑动窗口</p><p>仓库：<a href="https://github.com/ethz-asl/okvis" target="_blank" rel="noreferrer">https://github.com/ethz-asl/okvis</a> 论文：<a href="https://www.doc.ic.ac.uk/~sleutene/publications/ijrr2014_revision_1.pdf" target="_blank" rel="noreferrer">https://www.doc.ic.ac.uk/~sleutene/publications/ijrr2014_revision_1.pdf</a></p></li><li><p>VINS-Mono: 设备只要求单目，鲁棒性强，前端基于KLT跟踪算法， 后端基于滑动窗口的优化(采用ceres库)， DBoW的回环检测 仓库：<a href="https://github.com/HKUST-Aerial-Robotics/VINS-Mono%EF%BC%8C" target="_blank" rel="noreferrer">https://github.com/HKUST-Aerial-Robotics/VINS-Mono，</a> 论文：<a href="https://ieeexplore.ieee.org/document/8421746" target="_blank" rel="noreferrer">https://ieeexplore.ieee.org/document/8421746</a></p></li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://zhuanlan.zhihu.com/p/148412316" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/148412316</a></p><p><a href="https://blog.csdn.net/Night___Raid/article/details/108223615" target="_blank" rel="noreferrer">https://blog.csdn.net/Night___Raid/article/details/108223615</a></p><p><a href="https://www.cnblogs.com/hitcm/p/6327442.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/hitcm/p/6327442.html</a></p>',33)])])}const b=a(l,[["render",o]]);export{d as __pageData,b as default};
